frame.store("_veg_reply", { let __signature_127 = Signature { name: "_veg_reply".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_129 = Value::dict(); __attrs_129.dict_set(Value::from("__doc__"), Value::from("Five a day for the person asking, and a different answer for the person they name: the\n    adult advice (add a handful to what you cook) is not what helps a child who refuses the\n    stuff, and a grown-up who refuses it is not a child either.\n\n    The person is read from the line first and from the conversation after it, and a line that\n    says a pronoun and nothing anywhere else gets asked who it is: a child is named (\"my son\",\n    \"my 4 year old\") and an adult is named, so \"he\" on its own is nobody to guess at.\n    "))?; __attrs_129.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_130 = Value::dict(); __attrs_129.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_126 = Frame::module(frame.globals.clone()); let mut __function_128 = NativeFunction::qualified_with_origin("_veg_reply".into(), "_veg_reply".into(), "bot.knowledge.nutrition".into(), __attrs_129, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/nutrition.py", first: 315, last: 331, qualname: "_veg_reply" }, closure: __closure_126.clone(), freevars: vec![] }, move |rt, args| __py_9::_veg_reply(rt, __closure_126.clone(), &__signature_127, args)); __function_128 })?;
