let __v_146 = pyrt::literals::decode("{\"$dict\":[[\"calcium\",{\"$dict\":[[\"adult\",\"About 700mg of calcium a day for an adult, which is a pint of milk or a pot of yoghurt and a matchbox of cheese. Cheese, tinned sardines, almonds and fortified cereal all count, and the figure is the same for men and women.\"],[\"teen\",\"Teenagers need about 1,000mg of calcium a day for a boy and 800mg for a girl, which is a pint of milk plus a pot of yoghurt, with cheese or tinned sardines through the week. Those are the years the bones lay down their density, so it matters more now than it will at 30.\"]]}],[\"iron\",{\"$dict\":[[\"adult\",\"Men need about 9mg of iron a day and women about 15mg until the menopause, which is why women run low far more often. Red meat, lentils, beans, fortified cereal and dark green veg are the sources; vitamin C in the same meal helps you take it up, and tea or coffee with the meal blocks it.\"],[\"woman\",\"About 15mg of iron a day, which is nearly twice what a man needs, because of the monthly loss: lentils, beans, fortified cereal, red meat and dark green veg are the sources, and vitamin C in the same meal helps you take it up. Tea and coffee with food block it, so leave a gap either side.\"],[\"teen\",\"A teenage boy needs about 11mg of iron a day and a teenage girl about 15mg, because she loses some every month and both of them are growing fast. Lentils, beans, fortified cereal, red meat and dark green veg are the sources, and vitamin C at the same meal helps; tea and coffee with food work against it.\"]]}],[\"protein\",{\"$dict\":[[\"adult\",\"About 0.75g of protein per kilo of body weight a day, which is roughly 50g for a 65kg adult: a palm-sized portion at each meal covers it, from eggs, milk, beans, lentils, chicken or fish. You do not need to count grams to get there.\"],[\"teen\",\"A teenager needs about the same protein per kilo as an adult, so 45g to 55g a day for most of them: a palm-sized portion at each meal, and more if they are training hard or growing fast. Eggs, milk, beans, lentils, chicken and fish all count.\"]]}],[\"magnesium\",{\"$dict\":[[\"adult\",\"Men need about 300mg of magnesium a day and women about 270mg, and wholemeal bread, nuts, beans, green veg and dark chocolate cover it without any supplement. A supplement is for a low a doctor has actually found.\"]]}],[\"potassium\",{\"$dict\":[[\"adult\",\"The target is about 3,500mg a day, and most people fall short of it. A banana is about 430mg, so potatoes, beans, milk, fruit and vegetables are what closes the gap; there is no need for a supplement.\"]]}],[\"vitamin d\",{\"$dict\":[[\"adult\",\"Take 10 micrograms (400 IU) of vitamin D a day through autumn and winter, roughly October to March, and all year if you cover up or stay indoors. Take it as a supplement rather than hoping for it from food: oily fish, eggs and fortified spread will not get you there.\"],[\"teen\",\"Teenagers want the same 10 micrograms (400 IU) of vitamin D a day, from a supplement from October to March and all year if they cover up or are hardly outside. It is the one vitamin worth buying, because the food eaten will not supply it and the UK sun does not in winter.\"]]}],[\"vitamin c\",{\"$dict\":[[\"adult\",\"Aim for 40mg of vitamin C a day: one orange, a couple of peppers or a handful of broccoli covers it, so a supplement is money for nothing unless a doctor has told you otherwise. It also helps you take up the iron in beans and cereal at the same meal.\"]]}],[\"vitamin b12\",{\"$dict\":[[\"adult\",\"You need 1.5 micrograms of vitamin B12 a day, which any diet with meat, fish, covers easily. Vegans need it from fortified milk or cereal or a tablet, because plants do not make it and the stores you are born with run out after a few years.\"]]}],[\"folic acid\",{\"$dict\":[[\"adult\",\"Take 200 micrograms of folic acid a day as an adult, from a supplement or fortified cereal. If you are trying for a baby, or in the first 12 weeks of pregnancy, it is 400 micrograms and it wants starting before you conceive.\"]]}],[\"zinc\",{\"$dict\":[[\"adult\",\"Men need 9.5mg of zinc a day and women 7mg, which meat, beans, nuts, cheese and wholegrain cereal cover. More than 25mg a day for a long stretch works against copper, so a big zinc supplement is not a thing to take on a guess.\"]]}]]}")?;
