let __v_180 = pyrt::literals::decode("{\"$dict\":[[\"granola\",\"Granola is oats with oil and sugar baked on: fine, but it is a 40g portion - a 50g serving carries about 11g to 15g of sugar, so pick a bag under 10g per 100g.\"],[\"muesli\",\"Muesli is unbaked oats, nuts and dried fruit: more fibre than granola and less added sugar, though the raisins still count, so measure the bowl.\"],[\"cornflakes\",\"Cornflakes are refined flour with about 8g of sugar in a 30g bowl: the least filling of them for the calories.\"],[\"bran flakes\",\"Bran flakes and Weetabix are the wholegrain end, with several times the fibre of cornflakes for about the same calories.\"],[\"porridge\",\"Porridge is the plainest and the best everyday bowl: no added sugar, about 4g of fibre in 40g, and it keeps you full until lunch.\"]]}")?;
