frame.store("_pregnancy_vitamins", { let __signature_212 = Signature { name: "_pregnancy_vitamins".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_214 = Value::dict(); __attrs_214.dict_set(Value::from("__doc__"), Value::from("The supplement answer for a pregnancy, which is not the adult figure.\n\n    A pregnant person is the one group whose numbers are not the adult table: folic acid is\n    double for the first 12 weeks, vitamin D is wanted all year rather than in winter, and an\n    iron supplement is not something to start on a guess. The nutrition guard would otherwise\n    send every one of these lines to the conversation lane as a statement about the speaker.\n    "))?; __attrs_214.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_215 = Value::dict(); __attrs_214.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_211 = Frame::module(frame.globals.clone()); let mut __function_213 = NativeFunction::qualified_with_origin("_pregnancy_vitamins".into(), "_pregnancy_vitamins".into(), "bot.knowledge.nutrition".into(), __attrs_214, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/nutrition.py", first: 570, last: 607, qualname: "_pregnancy_vitamins" }, closure: __closure_211.clone(), freevars: vec![] }, move |rt, args| __py_13::_pregnancy_vitamins(rt, __closure_211.clone(), &__signature_212, args)); __function_213 })?;
let __v_216 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"iron\",\"ferritin\",\"anaemia\",\"anemia\",\"anaemic\",\"anemic\"]},\"Red meat, liver, lentils, beans, chickpeas, tofu, fortified cereal and dark green veg are the everyday sources, and a bowl of fortified cereal or a lentil curry is as good as a steak. Have vitamin C in the same meal - a glass of orange juice, peppers, tomatoes - because it can double how much you take up, and keep tea and coffee an hour away from the meal, since the tannins block it. A low a blood test has found is treated with tablets.\"]},{\"$tuple\":[{\"$tuple\":[\"calcium\"]},\"A pint of milk, or a pot of yoghurt and a matchbox-sized piece of cheese, covers the 700mg an adult needs. Tinned sardines or salmon with the bones, tofu set with calcium, fortified plant milk, and kale, broccoli or watercress are the ones that beat the dairy doubters. Vitamin D is what gets it into the bones, which is why the two are talked about together.\"]},{\"$tuple\":[{\"$tuple\":[\"vitamin d\",\"vit d\"]},\"Sun is the main source and food will not cover it: from about October to March in the UK the sun is too weak, so 10 micrograms (400 IU) a day from a supplement is the standard advice for everyone. Oil-rich fish, egg yolk, and fortified cereal or spread have some, but you would need a lot of them. Do not take more than 100 micrograms a day.\"]},{\"$tuple\":[{\"$tuple\":[\"b12\",\"vitamin b12\",\"b-12\"]},\"B12 is only in animal foods: meat, fish, milk, cheese and eggs, so a small pot of yoghurt or a portion of fish most days covers it. If you eat vegan, or very little of those, take a supplement (about 10 micrograms a day or 2000 a week) or choose plant milks with B12 added, because the body's stores last years and the shortage creeps up unnoticed.\"]},{\"$tuple\":[{\"$tuple\":[\"potassium\"]},\"Bananas get the credit, but potatoes, beans, lentils, tomatoes, spinach and orange juice have as much or more. Adults want about 3,500mg a day, and five portions of veg plus a potato or a banana gets most people there. If a kidney problem has been diagnosed, ask before adding potassium-rich food.\"]},{\"$tuple\":[{\"$tuple\":[\"magnesium\"]},\"Nuts, seeds, wholemeal bread, porridge oats, beans, lentils and dark green veg are the sources, and about 300mg a day covers an adult. A handful of nuts and a bowl of porridge is most of it. Supplements are only worth it if a blood test has shown a low.\"]},{\"$tuple\":[{\"$tuple\":[\"zinc\"]},\"Meat, shellfish, eggs, milk, beans, lentils and wholemeal bread are the sources, and adults need about 9.5mg a day for men and 7mg for women. Oysters, beef and pumpkin seeds are the richest. Taking zinc long-term at high doses upsets the copper balance, so a supplement is for a low a blood test has found.\"]},{\"$tuple\":[{\"$tuple\":[\"vitamin c\",\"vit c\"]},\"Peppers, oranges, kiwi, broccoli, tomatoes and potatoes with the skin on are the everyday sources, and a glass of orange juice is plenty for the day. Vitamin C is easily destroyed by heat, so steam or eat them raw where you can, and five portions of fruit and veg covers an adult without anything extra.\"]},{\"$tuple\":[{\"$tuple\":[\"folate\",\"folic acid\"]},\"Green veg, lentils, beans, oranges and fortified cereal are the everyday sources, and about 200 micrograms a day covers an adult without trying. Anyone pregnant, or trying for a baby, is advised 400 micrograms of folic acid a day as a supplement from before conception until 12 weeks, and that is not something food alone can cover.\"]},{\"$tuple\":[{\"$tuple\":[\"omega 3\",\"omega-3\",\"oily fish\",\"fish oil\"]},\"One portion of oily fish a week is the advice: salmon, mackerel, sardines, herring, trout, pilchards or fresh tuna, about 140g cooked. Tinned sardines or mackerel count and are the cheapest way. If you do not eat fish, walnuts, chia, flaxseed and rapeseed oil give the plant kind, which the body converts only a little of, so a supplement is reasonable for a vegan.\"]}]}")?;
