let __v_253 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"soy milk\",\"soya milk\",\"soy bean milk\",\"soybean milk\",\"soy\",\"soya\"]},\"Soya is the closest to milk: about 7g of protein in 200ml, the same as semi-skimmed, and it is the one to take if protein is what you are replacing. Check the carton says calcium and B12 added - those come from the fortification, not from the bean - and buy it unsweetened, because the sweetened soya is nearer a pudding.\"]},{\"$tuple\":[{\"$tuple\":[\"oat milk\",\"oat drink\",\"oatly\",\"oat\"]},\"Oat is the creamiest and the best in coffee and porridge: about 2g of protein in 200ml, and 7 to 8g of sugar that comes from the oats themselves rather than from a spoon. Buy the barista or no-added-sugar carton, and check it is fortified with calcium and B12, because unsweetened oat is thin on both.\"]},{\"$tuple\":[{\"$tuple\":[\"almond milk\",\"almond drink\",\"almond\"]},\"Almond is the lightest: about 1g of protein and 50 calories in 200ml, and thin in coffee. It is worth having only if the carton is fortified, since almonds are a small part of it, and it is no good at all for a nut allergy.\"]},{\"$tuple\":[{\"$tuple\":[\"coconut milk drink\",\"coconut drink\",\"coconut milk\"]},\"The coconut drink in a carton has almost no protein - about 0.5g in 200ml - and around 40 calories, and it tastes of coconut, so it is for a smoothie or a curry rather than a cup of tea. The tin of coconut milk is a cooking ingredient with 20g of fat a serving, not a milk to drink.\"]},{\"$tuple\":[{\"$tuple\":[\"rice milk\",\"rice drink\",\"rice\"]},\"Rice milk is sweet without added sugar and has about 1g of protein in 200ml, the least of them. It is not the drink for a child under five, because of the arsenic rice takes up; a fortified soya or oat carton is what a toddler should have instead.\"]},{\"$tuple\":[{\"$tuple\":[\"hemp milk\",\"hemp drink\",\"hemp\"]},\"Hemp has about 3g of protein in 200ml, a nutty taste and it does not split in hot coffee. It is the one to take if soya and nut milks are both out.\"]},{\"$tuple\":[{\"$tuple\":[\"pea milk\",\"pea protein milk\",\"pea\"]},\"Pea milk has about 6g of protein in 200ml, close to soya, and it froths well. It tastes of pea on its own, so it is better in coffee than in a glass.\"]}]}")?;
